"use strict";
import { createContext, useMemo } from "react";
import { ALL_NETWORKS_ARG } from "uniswap/src/data/rest/base";
import { useAbstractExploreStatsQuery } from "hooks/useAbstractExploreStats";
import { useProtocolStatsQuery } from "uniswap/src/data/rest/protocolStats";
import { useIsSupportedChainId } from "uniswap/src/features/chains/hooks/useSupportedChainId";
export const giveExploreStatDefaultValue = (value, defaultValue = 0) => {
  return value ?? defaultValue;
};
export const ExploreContext = createContext({
  exploreStats: {
    data: void 0,
    isLoading: false,
    error: false
  },
  protocolStats: {
    data: void 0,
    isLoading: false,
    error: false
  }
});
export const TABLE_PAGE_SIZE = 20;
export function ExploreContextProvider({
  chainId,
  children
}) {
  const isSupportedChain = useIsSupportedChainId(chainId);
  const isAbstractChain = chainId === 2741 || chainId === 11124;
  const {
    data: exploreStatsData,
    isLoading: exploreStatsLoading,
    error: exploreStatsError
  } = useAbstractExploreStatsQuery({
    chainId: isSupportedChain ? chainId?.toString() : ALL_NETWORKS_ARG
  });
  const {
    data: protocolStatsData,
    isLoading: protocolStatsLoading,
    error: protocolStatsError
  } = useProtocolStatsQuery(
    {
      chainId: isSupportedChain && !isAbstractChain ? chainId?.toString() : ALL_NETWORKS_ARG
    },
    {
      enabled: !isAbstractChain
      // Disable for Abstract chains to prevent SSL errors
    }
  );
  const mockProtocolStatsForAbstract = isAbstractChain ? {
    dailyProtocolTvl: {
      v2: [
        { timestamp: Date.now() / 1e3, value: 36494.8 },
        // Current V2 TVL from our subgraph
        { timestamp: Date.now() / 1e3 - 86400, value: 35e3 }
        // Previous day
      ],
      v3: [
        { timestamp: Date.now() / 1e3, value: 0 },
        // V3 TVL minimal
        { timestamp: Date.now() / 1e3 - 86400, value: 0 }
      ],
      v4: []
    },
    historicalProtocolVolume: {
      Month: {
        v2: [
          { timestamp: Date.now() / 1e3, value: 19192.84 },
          // Current V2 volume from our subgraph
          { timestamp: Date.now() / 1e3 - 86400, value: 18e3 }
          // Previous day
        ],
        v3: [
          { timestamp: Date.now() / 1e3, value: 0 },
          { timestamp: Date.now() / 1e3 - 86400, value: 0 }
        ],
        v4: []
      }
    }
  } : null;
  const exploreContext = useMemo(() => {
    return {
      exploreStats: {
        data: exploreStatsData,
        isLoading: exploreStatsLoading,
        error: !!exploreStatsError
      },
      protocolStats: {
        data: isAbstractChain ? mockProtocolStatsForAbstract : protocolStatsData,
        isLoading: isAbstractChain ? false : protocolStatsLoading,
        error: isAbstractChain ? false : !!protocolStatsError
      }
    };
  }, [
    exploreStatsData,
    exploreStatsError,
    exploreStatsLoading,
    protocolStatsData,
    protocolStatsError,
    protocolStatsLoading,
    isAbstractChain,
    mockProtocolStatsForAbstract
  ]);
  return <ExploreContext.Provider value={exploreContext}>{children}</ExploreContext.Provider>;
}
